const normalizeHeaders = (headers, normalizedName) => {
  for (const [k, v] of Object.entries(headers)) {
    if (k !== normalizedName && k.toUpperCase() === normalizedName.toUpperCase()) {
      headers[normalizedName] = v;
      delete headers[k];
    }
  }
}
