Until this gets added, you can use an object in the original `cancel` call, instead of a string or nothing, and then add some property to it. You could also do string parsing, but yuck. The problem with both of these approaches is if the `cancel` is in a different place from the interceptor and you can only change one of them.

For example, you could have an interceptor like (I only need the URL in my use case):

```
import {interceptors, cancel} from 'axios';

let loads = 0;

interceptors.request.use(request => {
    loads++;

    if(urlIsOurs(request.url)) {
        console.log('Request initiated from our server.');
        forceProgressBarShowing();
    } else {
        console.log('Request initiated from someone else's server.');
    }

    return request;
});

interceptors.response.use(() => {}, error => {
    const {request, response} = error || {};
    const config = response?.config || request?.config || error?.config;

    if(!urlIsUsable()) {
        console.log('Response errored from someone else's server.');
        return error;
    }

    console.log('Response errored from our server.');

    loads--;
    // sanity check
    if(loads < 0) {
        loads = 0;
    }

    if(!loads) {
        forceHideProgressBar();
    }

    return response;

    function urlIsUsable() {
        return urlIsOurs(config.url) || config.message.ourUrl;
    }
});
```

