export default class FetchLikeAxios {
	constructor(url = "", init = INIT, options = OPTIONS) {
		const { url: __url, ...initRest } = init;
		this.url = url || __url || "";
		this.init = initRest;
		this.options = Object.assign({}, OPTIONS, options);

		this.cookies = "";

		this.request = this.request.bind(this);
		this.get = this.get.bind(this);
		this.head = this.head.bind(this);
		this.options = this.options.bind(this);
		this.post = this.post.bind(this);
		this.put = this.put.bind(this);
		this.patch = this.patch.bind(this);
		this.delete = this.delete.bind(this);
	}

	request(init = INIT) {
		const { url = "", ...__init } = init;

		// Merge configs
		const reqInit = Object.assign({}, this.init, __init);

		// Serialize URL params
		let reqParams = "";
		if (reqInit.params !== undefined) {
			reqParams = this.options.paramsSerializer(reqInit.params);
		}

		// Build final URL
		const reqUrl = new URL(
			`${url}${(reqParams.length > 0) ? "?" : ""}${reqParams}`,
			this.url
		);

		// Create proper request headers, merge request and initial headers
		if (reqInit.headers !== undefined) {
			reqInit.headers = new Headers(mergeHeaders(this.init.headers, __init.headers));
		}

		// Include cookies when withCredentials allows it
		if (reqInit.withCredentials === true) {
			if (reqInit.headers === undefined) {
				reqInit.headers = new Headers();
			}

			// But only if no cookie header override has already been provided
			if (reqInit.headers.get("cookie") === null) {
				reqInit.headers.set("cookie", this.cookies);
			}
		}

		// Transform body before request, if any transformer functions are available
		if (reqInit.body !== undefined) {
			if (
				Array.isArray(this.options.transformRequest) &&
				(this.options.transformRequest.length > 0)
			) {
				const transformedBody = this.options.transformRequest.reduce((prev, transformer) => {
					return transformer(prev, reqInit.headers);
				}, reqInit.body);

				reqInit.body = transformedBody;
			}
		}

		// This will be the final response, same structure as Axios's
		let fetchResponse = {
			config: reqInit,

			// unfortunately, not using new Request() in this implementation
			// fetch() does accept a Request() instance
			// feel free to make such implementation, and populate this field
			request: null,

			// These will be populated later
			status: undefined,
			statusText: undefined,
			headers: {},
			data: undefined,
		};

		return fetch(reqUrl, reqInit)
			.then((response) => {
				fetchResponse.status = response.status;
				fetchResponse.statusText = response.statusText;
				fetchResponse.headers = Object.fromEntries(response.headers.entries());

				// Save any cookies sent by the server
				this.cookies = response.headers.get("set-cookie") || "";

				
				// Attempt to get JS object from JSON string
				const responseContentType = response.headers.get("content-type") || "";
				if (responseContentType.match(JSON_MIMETYPES_REGEX)) {
					return response.json();
				}

				// Return whatever the original body is
				return response.body;
			})
			.then((body) => {
				// Transform body before returning the response, if any transformer functions are available
				if (
					Array.isArray(this.options.transformResponse) &&
					(this.options.transformResponse.length > 0)
				) {
					fetchResponse.data = this.options.transformResponse.reduce((prev, transformer) => {
						return transformer(prev, body);
					}, reqInit.body);
				} else {
					fetchResponse.data = body;
				}

				// Validate status
				const validateStatus = (typeof this.options.validateStatus === "function")
					? this.options.validateStatus
					: defaultValidateStatus;

				if (validateStatus(fetchResponse.status) === true) {
					return Promise.resolve(fetchResponse);
				}

				return Promise.reject(fetchResponse);
			});
	}

	get(url = "", init = INIT) { return this.request({ ...init, url, method: "GET" }); }
	head(url = "", init = INIT) { return this.request({ ...init, url, method: "HEAD" }); }
	options(url = "", init = INIT) { return this.request({ ...init, url, method: "OPTIONS" }); }
	post(url = "", init = INIT) { return this.request({ ...init, url, method: "POST" }); }
	put(url = "", init = INIT) { return this.request({ ...init, url, method: "PUT" }); }
	patch(url = "", init = INIT) { return this.request({ ...init, url, method: "PATCH" }); }
	delete(url = "", init = INIT) { return this.request({ ...init, url, method: "DELETE" }); }
}
