    request.adapter = (config) => {
      return new Promise(() => {
        Promise.resolve({
          __cached: true,
          data: cachedResponse,
          status: 200,
          statusText: 'OK',
          headers: request.headers,
          config,
          request,
        })
      })
    }
  }
  return request;
});
this.instance.interceptors.response.use(async (response) => {
  if (response.__cached) {
    return response;
  } else {
    await putTheResponsePayloadIntoTheCache(response.data);
    return response;
  }
});
```
