  const parameterKeys = Object.keys(parameters);

  parameterKeys.forEach((parameterKey) => {
    const parameterValue = parameters[parameterKey];

    if (parameterValue) {
      if (isObject(parameterValue)) {
        newParameters.push(`${parameterKey}=${JSON.stringify(parameterValue)}`);
      } else {
        newParameters.push(`${parameterKey}=${parameterValue}`);
      }
    }
  });

  return newParameters.join('&');
};
```

