`adapter` allows custom handling of requests which makes testing easier. Return a promise and supply a valid response.

In axios, `fetch` meas the native fetch function. But you can also use any other function that returns a promise.

```javascript
import AxiosError from "axios/lib/core/AxiosError";

const customAdapter = (config) => {
  return new Promise((resolve, reject) => {
    // pretend this is a request result
    const isSuccess = Math.random() > 0.5;

    if (isSuccess) {
      // 返回的格式
      const response = {
        status: 200,
        statusText: "ok",
        config,
        request: "custom",
        data: {
          message: "success",
        },
      };
      resolve(response);
      return;
    } else {
      reject(new AxiosError("Network Error", AxiosError.ERR_NETWORK, config));
    }

    // 若设置了超时时间
    if (config.timeout) {
      timer = setTimeout(function () {
        reject(
          new AxiosError(
            "timeout of " + config.timeout + "ms exceeded",
            AxiosError.ETIMEDOUT,
            config
          )
        );
      }, config.timeout);
    }

    // 若定义了取消操作
    if (config.cancelToken || config.signal) {
      onCanceled = (cancel) => {
        // if (!request) {
        //   return;
        // }
        reject(
          !cancel || cancel.type
            ? new CanceledError(null, config, request)
            : cancel
        );
        // request.abort();
        // request = null;
      };

      config.cancelToken && config.cancelToken.subscribe(onCanceled);
      if (config.signal) {
        config.signal.aborted
          ? onCanceled()
          : config.signal.addEventListener("abort", onCanceled);
      }
    }
  });
};

const axios = Axios.create({
  adapter: customAdapter,
});
```

