router.post('/upload', upload.single('file'), async (req, res) => {
  if(!req.file) return res.status(400).json({ message: 'No file' });

  const rows = [];
  fs.createReadStream(req.file.path)
    .pipe(parse({ columns: true, trim: true }))
    .on('data', (row) => {
      rows.push(row);
    })
    .on('end', async () => {
      try {
        // Option: clear existing stats or upsert — here we upsert by ingameId or name
        for(const r of rows){
          const kills = Number(r.kills || 0);
          const headshots = Number(r.headshots || 0);
          const deaths = Number(r.deaths || 0);
          const headPerc = kills > 0 ? (headshots / kills) * 100 : 0;

          // Upsert by ingameId if present else by name
          const filter = r.ingameId ? { ingameId: r.ingameId } : { name: r.name };
          const update = { 
            name: r.name,
            ingameId: r.ingameId || '',
            kills, headshots, deaths,
            headshotPerc: Math.round(headPerc * 100) / 100
          };

          await Stat.findOneAndUpdate(filter, update, { upsert: true, new: true });
        }

        // delete temp file
        fs.unlinkSync(req.file.path);

        res.json({ message: 'Uploaded and saved' });
      } catch (err) {
        res.status(500).json({ error: err.message });
      }
    })
    .on('error', (err) => {
      fs.unlinkSync(req.file.path);
